import {TOWN_LAYOUTS,townLayout,project} from './town-life/layouts.mjs';
import {townForPreset} from './town-life/tile-state.mjs';
// Dense, metre-scale district grammars. Displayed households do not multiply the six-resident demo.
export const DISTRICT_SCENES={
 neighborhood:{label:'Neighborhood',name:'Neighborhood court',presets:{court:'Garden court',lane:'Shared lane'},purpose:'Connect household doors to shared water, gardens, rest and neighborhood routes.',uses:['six simulated residents','illustrative neighbors'],inputs:['food','fuel','water'],outputs:['household life'],capabilities:{housing:6},limitations:['Six residents simulated across the whole settlement','Additional households illustrate urban form; no extra population or workforce']},
 town:{label:'Town',name:'Town street',presets:Object.fromEntries(Object.entries(TOWN_LAYOUTS).map(([k,v])=>[k,v.label])),purpose:'Arrange household frontages and public exchange along a connected street.',uses:['households','workers','schoolchildren'],inputs:['food','fuel','water','surplus'],outputs:['public exchange and household life'],capabilities:{housing:6},limitations:['Outside suppliers cover shortages; quantities are game abstractions','Town household economy is independent of the six-resident settlement demo']}
};
const item=(asset,x,z,purpose,extra={})=>({asset,x,z,y:0,angle:0,purpose,...extra});
const transform=(o,x,z,angle)=>({...o,x:x+o.x*Math.cos(angle)+o.z*Math.sin(angle),z:z-o.x*Math.sin(angle)+o.z*Math.cos(angle),angle:angle+(o.angle||0)});
function household(x,z,side,index,seed){const angle=side<0?Math.PI/2:-Math.PI/2;return [
 item('GF-191',0,-3,'household shelter'),item('roof',0,-3,'pitched weather cover',{y:2.62,size:[6.4,1.4,5.4],roofShape:'gable',roofColor:(index+seed)%3===0?'#416c65':'#a37a4c'}),
 item('GF-014',4,1,'household water'),item('WW-003',4,-1,'dry household fuel'),item('BA-0018',-3,2,'front-door rest'),item('BA-0088',1.5,2.8,'illustrative neighbor')
 ].map(o=>transform(o,x,z,angle));}
export function districtRequirements(type,preset,seed=41,stage=3){
 if(!DISTRICT_SCENES[type]?.presets[preset])throw Error('Unknown district preset');
 if(type==='town')return townRequirements(preset,seed,stage);
 if(type==='neighborhood'){const req=townRequirements(preset==='lane'?'post':'green',seed,preset==='lane'?2:1)[0];return [{...req,role:type,items:req.items.map(o=>o.purpose==='shared well'?{...o,purpose:'shared neighborhood water'}:o),purpose:DISTRICT_SCENES[type].purpose}];}
 const town=type==='town',rows=town?(preset==='market'?[-21,-7,7,21]:[-20,0,20]):(preset==='lane'?[-20,0,20]:[-16,16]),x=town?(preset==='market'?10:14):13,items=[],paths=[[{x:0,z:34},{x:0,z:-32}]];let index=0;
 for(const side of [-1,1])for(const z of rows){items.push(...household(side*x,z,side,index++,seed));paths.push([{x:0,z},{x:side*x,z}]);if(town&&preset==='market'){items.push(item('soil',side*19.5,z,'illustrative household kitchen plot',{y:.02,size:[3,.04,4]}));for(let row=0;row<3;row++)for(let col=0;col<4;col++)items.push(item('GF-004',side*(18.4+col*.7),z-1.1+row*.8,'illustrative household crop'));}}
 if(town){for(const side of [-1,1])for(const z of [-14,14]){const x=side*5;items.push(item('GF-017',x,z,'public exchange shade'),item('BA-0012',x,z+1.5,'surplus exchange table'),item('BA-0024',x+side*2,z+1,'vessels offered for exchange'),item('BA-0083',x,z-3,'illustrative trader'));paths.push([{x:0,z:z+4},{x,z:z+4}]);}
  if(preset==='civic')for(const side of [-1,1])items.push(item('GF-194',side*6,0,'civic court seating',{angle:side*Math.PI/2}));
 }else{for(const side of [-1,1]){items.push(item('GF-194',side*6,-4,'shared garden seating',{angle:side*Math.PI/2}),item('GF-014',side*6,4,'shared neighborhood water'));paths.push([{x:0,z:6},{x:side*6,z:6}]);for(let row=0;row<3;row++)for(let col=0;col<4;col++)items.push(item('GF-004',side*(22+col*.85),-3+row*.9,'illustrative kitchen garden'));}}
 for(const side of [-1,1])for(const z of [-10,10])items.push(item('WW-001',side*28,z,'regrowing planted district edge'));
 return [{role:type,w:48,d:60,radius:32,anchor:{x:0,z:0},hub:{x:0,z:36},exteriorAccess:{x:0,z:34},accessScope:'working-entrances',internalPaths:paths,internalPathWidths:paths.map((_,i)=>i===0?3.2:1.4),items:town?items.filter(o=>!['BA-0088','BA-0083'].includes(o.asset)):items,purpose:DISTRICT_SCENES[type].purpose,index:0}];
}
export function districtRecipe(type,preset,seed,stage=3){return {...(type==='town'?{townLife:townForPreset(preset,seed,stage),growthStage:stage}:{}),generator:'district-composer',version:1,type,preset,seed,requirements:districtRequirements(type,preset,seed,stage),landscape:{height:0,vegetation:2,props:0,seed:seed^173},tiles:[{id:type,type,cell:0,rotation:0,seed}]};}
export function describeDistrict(type,preset){if(type==='town')return DISTRICT_SCENES[type].presets[preset]+'. '+TOWN_LAYOUTS[preset].inspiration+' Gentle topography with level home foundations. This is a spatial interpretation, not a historical reconstruction. It has working households, shopping, school and civic services. Outside suppliers cover shortages.';return DISTRICT_SCENES[type].presets[preset]+' connects household doors, public stops and planted edges along a continuous street. Six residents participate in the settlement simulation; additional homes and traders illustrate the place without adding population or production.';}

function townRequirements(preset,seed,stage=3){
 const d=townLayout(preset,seed,stage),items=[],paths=d.paths.map(p=>p.map(([x,z])=>({x,z})));
 d.homes.forEach((h,i)=>{items.push(...household(0,0,-1,i,seed).filter(o=>o.asset!=='BA-0088').map(o=>transform(o,h.x,h.z,h.angle-Math.PI/2)));const back={x:h.center[0]-Math.sin(h.angle)*4.7,z:h.center[1]-Math.cos(h.angle)*4.7};items.push(item('soil',back.x,back.z,'household kitchen patch',{y:.02,size:[2.2,.04,2.8],angle:h.angle}));for(let j=0;j<3;j++)items.push(item('GF-004',back.x+(j-1)*.65,back.z,'kitchen herbs',{angle:h.angle}));});
 const [cx,cz]=d.heart;
 for(const [asset,purpose,radius]of [['BA-0012','surplus exchange table',.89],['GF-017','public exchange shade',1.68],['GF-014','shared well',.76],['GF-194','common seating',.92]]){let point;for(let n=0;n<160&&!point;n++){const angle=n*2.399963,range=4+Math.floor(n/24)*1.7,x=cx+Math.sin(angle)*range,z=cz+Math.cos(angle)*range;if(Math.hypot(x,z)>26||d.homes.some(h=>Math.hypot(x-h.center[0],z-h.center[1])<5)||items.some(o=>Math.hypot(x-o.x,z-o.z)<radius+1.5))continue;if(d.paths.every(p=>p.slice(1).every((b,i)=>{const q=project([x,z],p[i],b);return Math.hypot(x-q[0],z-q[1])>radius+.9;})))point={x,z,angle};}if(point)items.push(item(asset,point.x,point.z,purpose,{angle:point.angle}));}
 for(const [x,z]of d.planting)items.push(item('WW-001',x,z,'orchard and shaded residual space',{angle:(x+z)*.1}));
 return [{role:'town',w:48,d:60,radius:32,anchor:{x:0,z:0},hub:{x:0,z:36},exteriorAccess:{x:0,z:34},accessScope:'working-entrances',internalPaths:paths,internalPathWidths:paths.map((_,i)=>i===0?2.6:i<d.lanes.length?1.9:1.2),items:items.filter(o=>{if(['GF-191','roof','soil'].includes(o.asset))return true;if(Math.hypot(o.x,o.z)>29)return false;const radius=({'GF-014':.76,'WW-001':.83,'GF-017':1.68,'GF-194':.92,'BA-0012':.89,'WW-003':.66,'BA-0018':.38,'GF-004':.44})[o.asset]||1;return d.paths.every(path=>path.slice(1).every((b,i)=>{const q=project([o.x,o.z],path[i],b);return Math.hypot(o.x-q[0],o.z-q[1])>radius+.85;}));}),purpose:d.inspiration,index:0,townTerrain:{preset,seed},growth:{stage,events:d.events,homes:d.homes.length,targetHomes:d.targetHomes}}];
}
